    ["PZ_Map"] = {
        ["Copy this URL to your browser's address bar to see/bookmark a live world map. "] = "UI_HxMO_PZMap_4d76b6",
        ["PROTON DETECTED. The address below uses Wine's internal drives (C:, S:), which your Linux browser cannot open. Replace the C:/users/steamuser/ part with the real Linux path to your Proton prefix - it lives under steamapps/compatdata/108600/pfx/drive_c/users/steamuser/ inside whichever Steam library holds Project Zomboid. The page path before the question mark needs the same treatment."] = "UI_HxMO_PZMap_6b85be",
        ["Easiest way to find it: search your file manager for a folder named PZ_Map containing heartbeat.txt. That folder is what the ?d= part must point at, and it needs a trailing slash."] = "UI_HxMO_PZMap_4c3222",
