        ["Show breath below (°C)"] = "UI_HxMO_FoggyBreath_showBelowC",
        ["Breath appears when the air around a character is colder than this. Fires, heaters and buildings warm the air, so standing by a campfire can stop it. Drag right to see breath more often."] = "UI_HxMO_FoggyBreath_showBelowC_tt",
        ["Puffs per breath"] = "UI_HxMO_FoggyBreath_puffCount",
