        ["Puff size"] = "UI_HxMO_FoggyBreath_puffSize",
        ["Size of each cloud. They start small and grow as they fade."] = "UI_HxMO_FoggyBreath_puffSize_tt",
        ["Opacity (%)"] = "UI_HxMO_FoggyBreath_opacity",
        ["How visible the breath is. Low values give a subtle haze, high values a thick white cloud."] = "UI_HxMO_FoggyBreath_opacity_tt",
        ["Seconds between breaths"] = "UI_HxMO_FoggyBreath_calmSeconds",
        ["Time between exhales while calm and standing still. Running, exhaustion and panic make breaths come up to three times faster than this."] = "UI_HxMO_FoggyBreath_calmSeconds_tt",
        ["Puff lifetime (seconds)"] = "UI_HxMO_FoggyBreath_lifeSeconds",
        ["How long each cloud stays before it has fully faded."] = "UI_HxMO_FoggyBreath_lifeSeconds_tt",
        ["Calm breath force (%)"] = "UI_HxMO_FoggyBreath_breathForce",
        ["How far a relaxed breath pushes out from the mouth. Tired or panicked breathing always ramps up to full force (100%), so this is the gentle end of the scale."] = "UI_HxMO_FoggyBreath_breathForce_tt",
        ["Heavy breathing strength (%)"] = "UI_HxMO_FoggyBreath_stressBoost",
        ["How strongly exhaustion, panic and running change the breathing: faster, bigger and more forceful. 0 turns heavy breathing off, 200 makes it very dramatic."] = "UI_HxMO_FoggyBreath_stressBoost_tt",
        ["Show breath indoors"] = "UI_HxMO_FoggyBreath_indoors",
