        ["Aim (right mouse) raises the sights"] = "UI_HxMO_ProjectViewpointADS_f2693b",
        ["Hold the ADS key while aiming"] = "UI_HxMO_ProjectViewpointADS_cfd661",
        ["Hip fire; ADS key toggles sights (remembered)"] = "UI_HxMO_ProjectViewpointADS_5b6e91",
        ["ADS key"] = "UI_HxMO_ProjectViewpointADS_key",
        ["Used by the hold and toggle modes."] = "UI_HxMO_ProjectViewpointADS_key_tt",
        ["Aiming takes priority over menus"] = "UI_HxMO_ProjectViewpointADS_aimPriority",
        ["While you hold a firearm, the ADS key does not open the vehicle / animal radial menu that shares it (V), and Viewpoint Interface's interaction prompt and action menu step aside while you aim. Lower the gun or holster it to use them."] = "UI_HxMO_ProjectViewpointADS_aimPriority_tt",
        ["ADS from third person switches to first person"] = "UI_HxMO_ProjectViewpointADS_thirdAds",
        ["In third person, raising the sights switches to first person and lowering them switches back. Hip fire stays in third person."] = "UI_HxMO_ProjectViewpointADS_thirdAds_tt",
        ["ADS transition speed"] = "UI_HxMO_ProjectViewpointADS_speed",
        ["Multiplies every weapon's raise time (higher = faster)."] = "UI_HxMO_ProjectViewpointADS_speed_tt",
        ["ADS mouse sensitivity"] = "UI_HxMO_ProjectViewpointADS_adsSens",
        ["Magnified scope sensitivity"] = "UI_HxMO_ProjectViewpointADS_scopeSens",
        ["1.0 keeps the same feel per degree of view at every magnification."] = "UI_HxMO_ProjectViewpointADS_scopeSens_tt",
        ["Hide Viewpoint's crosshair while aiming down sights"] = "UI_HxMO_ProjectViewpointADS_hideCrosshair",
        ["Stop the gun clipping open near the camera while aiming"] = "UI_HxMO_ProjectViewpointADS_closeClip",
        ["Moves the camera's near clip plane from 5 cm to about 1 cm while sights are up, so the receiver and stock right under your eye are drawn instead of being cut open."] = "UI_HxMO_ProjectViewpointADS_closeClip_tt",
        ["No depth-of-field blur while aiming down sights"] = "UI_HxMO_ProjectViewpointADS_adsSharp",
        ["Viewpoint shader packs with depth of field focus on the screen centre, which is your sights when ADS, so the world blurs. This keeps the view sharp while sights are up."] = "UI_HxMO_ProjectViewpointADS_adsSharp_tt",
        ["Iron sight / red dot distance (long guns)"] = "UI_HxMO_ProjectViewpointADS_ironDist",
        ["How far in front of your eye the gun sits when aiming down sights. Higher = smaller front sight, more of the target visible and less of your hands near the camera, but past about 1.3 the arms stretch to reach. Pistols are not affected. Does not change where you hit."] = "UI_HxMO_ProjectViewpointADS_ironDist_tt",
        ["Weapon handling feel (visual)"] = "UI_HxMO_ProjectViewpointADS_4e2f0c",
        ["Weapon sway"] = "UI_HxMO_ProjectViewpointADS_sway",
        ["Breathing sway, affected by aiming skill, endurance, fatigue, panic, movement and weapon weight."] = "UI_HxMO_ProjectViewpointADS_sway_tt",
        ["Sway amount"] = "UI_HxMO_ProjectViewpointADS_swayAmount",
        ["Camera recoil"] = "UI_HxMO_ProjectViewpointADS_cameraRecoil",
        ["Each shot climbs the view and pushes it a little sideways. Part of it settles back, the rest stays: hold the gun down on full auto. Every weapon kicks its own way (pistols snap, rifles push, snipers and shotguns punch)."] = "UI_HxMO_ProjectViewpointADS_cameraRecoil_tt",
        ["Recoil amount"] = "UI_HxMO_ProjectViewpointADS_recoilAmount",
        ["Scales the view climb and the visible gun kick."] = "UI_HxMO_ProjectViewpointADS_recoilAmount_tt",
        ["Hip-fire spread"] = "UI_HxMO_ProjectViewpointADS_hipSpread",
        ["Shots from the hip go somewhere inside a cone that depends on the weapon (wide for snipers and machine guns, tight for pistols), grows while moving or running and shrinks with Aiming skill. Aim down the sights to hit at range. Works with Viewpoint True Ballistics."] = "UI_HxMO_ProjectViewpointADS_hipSpread_tt",
        ["Weapon inertia when turning"] = "UI_HxMO_ProjectViewpointADS_inertia",
        ["Physical weapon presence"] = "UI_HxMO_ProjectViewpointADS_6f0e9e",
        ["Physical weapon collision"] = "UI_HxMO_ProjectViewpointADS_presence",
        ["Your gun occupies real space: near walls, closed doors and windows, tall furniture and vehicles it slides back and rises into a compressed ready instead of passing through, and returns exactly to your sights when there is room again. Long rifles need more room than pistols. First and third person, hip and ADS. Visual and handling only (client side); shots still leave along your aim. Untick to switch the whole system off."] = "UI_HxMO_ProjectViewpointADS_presence_tt",
        ["Other players' guns collide too"] = "UI_HxMO_ProjectViewpointADS_presenceOthers",
        ["Other players' guns also give way at walls, doors and furniture on your screen. Worked out on your own game from what it already knows about them (no network traffic, nothing needed on the server); players who run this mod see yours the same way. Up to 12 nearest aiming players within 40 tiles."] = "UI_HxMO_ProjectViewpointADS_presenceOthers_tt",
        ["Collision start distance (cm)"] = "UI_HxMO_ProjectViewpointADS_presenceStart",
        ["How far in front of an obstacle the muzzle starts giving way."] = "UI_HxMO_ProjectViewpointADS_presenceStart_tt",
        ["Compressed pose strength"] = "UI_HxMO_ProjectViewpointADS_presenceStrength",
        ["How far the gun pulls back and rises when it meets something."] = "UI_HxMO_ProjectViewpointADS_presenceStrength_tt",
        ["Collision smoothing"] = "UI_HxMO_ProjectViewpointADS_presenceSmoothing",
        ["Lower = snappier, higher = softer movement into and out of the compressed pose."] = "UI_HxMO_ProjectViewpointADS_presenceSmoothing_tt",
        ["Low ready when not aiming (first person)"] = "UI_HxMO_ProjectViewpointADS_lowReady",
        ["Lowers the muzzle a little while you hold a firearm without aiming. Off by default."] = "UI_HxMO_ProjectViewpointADS_lowReady_tt",
        ["Low ready amount"] = "UI_HxMO_ProjectViewpointADS_lowReadyAmount",
        ["Optics"] = "UI_HxMO_ProjectViewpointADS_beea0f",
        ["Scope eye box (lens shadow when misaligned)"] = "UI_HxMO_ProjectViewpointADS_eyeBox",
        ["Scope lens size on screen"] = "UI_HxMO_ProjectViewpointADS_lensSize",
        ["Scope zoom"] = "UI_HxMO_ProjectViewpointADS_scopeZoom",
        ["Multiplies the zoom of 2x/4x/8x scopes. 1.0 = the scope's own number against Viewpoint's wide view; 1.5 = a 4x scope zooms 6x."] = "UI_HxMO_ProjectViewpointADS_scopeZoom_tt",
        ["Reticle brightness"] = "UI_HxMO_ProjectViewpointADS_brightness",
        ["Illuminated reticle colour"] = "UI_HxMO_ProjectViewpointADS_color",
        ["Red"] = "UI_HxMO_ProjectViewpointADS_ee38e4",
        ["Green"] = "UI_HxMO_ProjectViewpointADS_d38281",
        ["Amber"] = "UI_HxMO_ProjectViewpointADS_88068e",
        ["Black"] = "UI_HxMO_ProjectViewpointADS_e90dfb",
        ["Picture-in-picture scopes and sights"] = "UI_HxMO_ProjectViewpointADS_pipScopes",
        ["Scopes show their magnified view inside the scope's glass, and red dots / holo sights show the world clearly through their window with the lit reticle, while the rest of the screen, the gun and your hands stay normal. Renders the world a second time while aiming through an optic, so it costs some frame rate. Untick for the classic full-screen scope view. If it ever fails it switches itself off and the classic view is used."] = "UI_HxMO_ProjectViewpointADS_pipScopes_tt",
        ["Picture-in-picture quality"] = "UI_HxMO_ProjectViewpointADS_pipQuality",
        ["How much work the view inside scopes and sights costs. All levels only draw the part of the world the lens shows. High: everything, every frame (rain and object outlines in the lens too). Mid: no rain particles or outlines inside the lens. Low: like Mid, but the lens picture is redrawn every other frame (can lag a little when turning fast)."] = "UI_HxMO_ProjectViewpointADS_pipQuality_tt",
        ["High"] = "UI_HxMO_ProjectViewpointADS_655d20",
        ["Mid (default)"] = "UI_HxMO_ProjectViewpointADS_2dd4a3",
        ["Low"] = "UI_HxMO_ProjectViewpointADS_28d0ed",
        ["Without picture-in-picture, magnified scopes magnify the whole first-person view behind a lens mask."] = "UI_HxMO_ProjectViewpointADS_b63eb2",
        ["Scope zoom and zeroing"] = "UI_HxMO_ProjectViewpointADS_ba8ff6",
        ["Variable zoom on high-power scopes"] = "UI_HxMO_ProjectViewpointADS_variableZoom",
        ["Scopes of 4x and up zoom in steps: an 8x goes 2x / 4x / 8x, a 6x 1.5x / 3x / 6x, a 4x 2x / 4x. Optics registered with their own zoom levels always use them."] = "UI_HxMO_ProjectViewpointADS_variableZoom_tt",
        ["Mouse wheel changes scope zoom"] = "UI_HxMO_ProjectViewpointADS_wheelZoom",
        ["While looking through a variable scope: wheel up zooms in, wheel down zooms out."] = "UI_HxMO_ProjectViewpointADS_wheelZoom_tt",
        ["Scope zoom in (key)"] = "UI_HxMO_ProjectViewpointADS_zoomInKey",
        ["Optional key, as well as the wheel."] = "UI_HxMO_ProjectViewpointADS_zoomInKey_tt",
        ["Scope zoom out (key)"] = "UI_HxMO_ProjectViewpointADS_zoomOutKey",
        ["Zeroing up"] = "UI_HxMO_ProjectViewpointADS_zeroUpKey",
        ["Raises the sight's zero range one step (DayZ style), while you hold a firearm. Needs Viewpoint True Ballistics: that is where bullets drop, so that is where the zero matters."] = "UI_HxMO_ProjectViewpointADS_zeroUpKey_tt",
        ["Zeroing down"] = "UI_HxMO_ProjectViewpointADS_zeroDownKey",
        ["Lowers the sight's zero range one step."] = "UI_HxMO_ProjectViewpointADS_zeroDownKey_tt",
        ["Show zoom and zero when changed"] = "UI_HxMO_ProjectViewpointADS_scopeHud",
        ["A small readout in the lower right corner for a moment after you change the zoom or the zero."] = "UI_HxMO_ProjectViewpointADS_scopeHud_tt",
        ["Developer"] = "UI_HxMO_ProjectViewpointADS_672caf",
        ["Developer / calibration mode"] = "UI_HxMO_ProjectViewpointADS_developer",
